type AccessReport struct {
	// AskedAbout The identity Alder put the question about: a DN, or `anonymous`.
	// Added in 1.28.
	//
	// Present whether or not there is a verdict, which is what makes it
	// worth having: `effective` is absent entirely when the server
	// cannot answer or declines, and then nothing else in the response
	// says who was asked about.
	AskedAbout *string `json:"askedAbout,omitempty"`

	// Disclaimer One sentence saying what the report is and is not, so every surface
	// says the same thing.
	Disclaimer string `json:"disclaimer"`
	Dn         string `json:"dn"`

	// Effective What the server itself says an identity may do on this entry, from the
	// Get Effective Rights control (1.19 reads rules; this is the directory's
	// own verdict, added in 1.20). It outranks the rules: the rules are what
	// is written, this is what the server will do.
	Effective *EffectiveRights `json:"effective,omitempty"`

	// RightsNote Why there is no verdict from the server: it cannot answer that
	// question, or it declined this one. Neither is "no rights".
	RightsNote *string      `json:"rightsNote,omitempty"`
	Rules      []AccessRule `json:"rules"`

	// Styles The mechanisms rules were found in, named after the attribute that
	// carries them: `aci`, `olcAccess`.
	Styles []string `json:"styles"`

	// Unread Places rules could live that this session could not read, so the
	// report is not the whole answer. The common one: OpenLDAP keeps its
	// rules in the configuration tree, which usually needs its own
	// identity.
	Unread *[]AccessUnread `json:"unread,omitempty"`
}

